/** Browser-only photo ingest. Compress to JPEG so the season file stays carryable. */

import type { SurveyPhoto } from "./types";
import { surveyId } from "./ops";
import { VAN_SCHEMATIC_PX, vanSchematicPhoto } from "./van-layout";

const MAX_EDGE = 2400;
const QUALITY = 0.82;

export async function fetchPhotoFile(url: string, name: string): Promise<SurveyPhoto> {
  const res = await fetch(url);
  if (!res.ok) throw new Error("Could not load that photograph.");
  const blob = await res.blob();
  const file = new File([blob], name, { type: blob.type || "image/jpeg" });
  return readPhotoFile(file);
}

export async function readPhotoFile(file: File): Promise<SurveyPhoto> {
  const bmp = await createImageBitmap(file);
  const scale = Math.min(1, MAX_EDGE / Math.max(bmp.width, bmp.height));
  const w = Math.max(1, Math.round(bmp.width * scale));
  const h = Math.max(1, Math.round(bmp.height * scale));
  const canvas = document.createElement("canvas");
  canvas.width = w;
  canvas.height = h;
  const ctx = canvas.getContext("2d");
  if (!ctx) throw new Error("Could not read the photograph.");
  ctx.drawImage(bmp, 0, 0, w, h);
  bmp.close();
  const dataUrl = canvas.toDataURL("image/jpeg", QUALITY);
  return {
    id: surveyId("photo"),
    name: file.name.replace(/\.[^.]+$/, "") || "Satellite",
    dataUrl,
    mime: "image/jpeg",
    pixelWidth: w,
    pixelHeight: h,
    scale: null,
    worldOriginInches: { x: 0, y: 0 },
    worldRotationDeg: 0,
  };
}

export function paintVanSchematic(): SurveyPhoto {
  const w = VAN_SCHEMATIC_PX.width;
  const h = VAN_SCHEMATIC_PX.height;
  const canvas = document.createElement("canvas");
  canvas.width = w;
  canvas.height = h;
  const ctx = canvas.getContext("2d");
  if (!ctx) return vanSchematicPhoto();
  ctx.fillStyle = "#6e8444";
  ctx.fillRect(0, 0, w, h);
  ctx.fillStyle = "#7b9150";
  ctx.fillRect(20, 20, w - 40, h - 40);
  ctx.strokeStyle = "#d7c4a0";
  ctx.lineWidth = 6;
  ctx.strokeRect(16, 16, w - 32, h - 32);
  ctx.fillStyle = "#c4b089";
  ctx.fillRect(Math.round(w * 0.22), 16, 10, h - 32);
  ctx.fillStyle = "rgba(246, 241, 231, 0.35)";
  ctx.font = "28px Georgia, serif";
  ctx.fillText("Van Complex — schematic 300 × 120 yd", 36, 56);
  ctx.font = "18px sans-serif";
  ctx.fillText("12U", 48, h / 2);
  ctx.fillText("10U", Math.round(w * 0.28), h / 2);
  ctx.fillText("6U / 8U", Math.round(w * 0.46), h / 2);
  ctx.fillText("16U", Math.round(w * 0.78), h / 2);
  return vanSchematicPhoto(canvas.toDataURL("image/jpeg", QUALITY));
}
