<script lang="ts">
  import type { SearchHit } from "../search";

  let {
    getHits,
    onJump,
  }: {
    getHits: (q: string) => SearchHit[];
    onJump: (hit: SearchHit) => void;
  } = $props();

  let q = $state("");
  let open = $state(false);
  let active = $state(0);
  let box: HTMLDivElement | undefined = $state();

  const hits = $derived(q.trim() ? getHits(q) : []);

  $effect(() => {
    if (active >= hits.length) active = 0;
  });

  function onInput(e: Event) {
    q = (e.currentTarget as HTMLInputElement).value;
    open = true;
    active = 0;
  }

  function jump(hit: SearchHit) {
    open = false;
    onJump(hit);
  }

  function onKey(e: KeyboardEvent) {
    if (e.key === "Escape") {
      open = false;
      return;
    }
    if (!open && (e.key === "ArrowDown" || e.key === "Enter") && hits.length) open = true;
    if (!hits.length) return;
    if (e.key === "ArrowDown") {
      e.preventDefault();
      active = (active + 1) % hits.length;
    } else if (e.key === "ArrowUp") {
      e.preventDefault();
      active = (active - 1 + hits.length) % hits.length;
    } else if (e.key === "Enter") {
      const hit = hits[active];
      if (hit) {
        e.preventDefault();
        jump(hit);
      }
    }
  }

  function onDoc(e: MouseEvent) {
    if (box && !box.contains(e.target as Node)) open = false;
  }
</script>

<svelte:window onclick={onDoc} />

<div class="search-host" data-search-widget bind:this={box}>
  <input
    data-field="search"
    class="search"
    type="search"
    role="combobox"
    placeholder="Jump to a team, person, field, Saturday…"
    autocomplete="off"
    aria-autocomplete="list"
    aria-expanded={open && hits.length ? "true" : "false"}
    aria-controls="van-search-results"
    value={q}
    oninput={onInput}
    onkeydown={onKey}
    onfocus={() => (open = true)}
  />
  {#if open && q.trim() && hits.length}
    <ul id="van-search-results" class="search-results" data-search-results role="listbox">
      {#each hits as hit, i (hit.id)}
        <li
          role="option"
          aria-selected={i === active}
          class:is-active={i === active}
          data-search-hit
          data-kind={hit.kind}
          data-search-id={hit.id}
          data-game={hit.gameId || undefined}
        >
          <button type="button" onpointerdown={(e) => e.preventDefault()} onclick={() => jump(hit)}>
            <span class="kind" data-search-kind={hit.kind}>{hit.kind}</span>
            <span class="lab">{hit.label}</span>
            <span class="hint">{hit.hint}</span>
          </button>
        </li>
      {/each}
    </ul>
  {/if}
</div>
