/** Local tangent plane at a campus GCP. Inches are still the record; lat/lng is a display. */

import { headingUnit, hypot, photoWorldSize, pixelToWorld } from "./geometry";
import type { AssociationSurvey, PhotoCheck, Pt, SurveyEnu, SurveyPhoto } from "./types";
import { yardsToInches } from "./units";

const M_PER_INCH = 0.0254;
const M_PER_DEG_LAT = 111_320;

/** Flag a check when the tape disagrees with the scale by more than this. */
export const CHECK_WARN_PCT = 2;

export function metersPerDegLng(lat: number): number {
  return M_PER_DEG_LAT * Math.cos((lat * Math.PI) / 180);
}

export function northHeading(photo: SurveyPhoto): number | null {
  return photo.geodesy ? photo.geodesy.northDeg : null;
}

export function gcpWorld(photo: SurveyPhoto): Pt | null {
  const g = photo.geodesy;
  if (!g) return null;
  return pixelToWorld(photo, g.px, g.py);
}

export function worldToLatLng(photo: SurveyPhoto, p: Pt): { lat: number; lng: number } | null {
  const g = photo.geodesy;
  const gcp = gcpWorld(photo);
  if (!g || !gcp) return null;
  const n = headingUnit(g.northDeg);
  const e = headingUnit(g.northDeg + 90);
  const dx = p.x - gcp.x;
  const dy = p.y - gcp.y;
  const northInches = dx * n.x + dy * n.y;
  const eastInches = dx * e.x + dy * e.y;
  return {
    lat: g.lat + (northInches * M_PER_INCH) / M_PER_DEG_LAT,
    lng: g.lng + (eastInches * M_PER_INCH) / metersPerDegLng(g.lat),
  };
}

export function formatLatLng(lat: number, lng: number): string {
  const ns = lat >= 0 ? "N" : "S";
  const ew = lng >= 0 ? "E" : "W";
  return `${Math.abs(lat).toFixed(6)}°${ns}  ${Math.abs(lng).toFixed(6)}°${ew}`;
}

export function latLngToWorld(enu: SurveyEnu, lat: number, lng: number): Pt {
  const northM = (lat - enu.lat) * M_PER_DEG_LAT;
  const eastM = (lng - enu.lng) * metersPerDegLng(enu.lat);
  const n = headingUnit(enu.northDeg);
  const e = headingUnit(enu.northDeg + 90);
  const northInches = northM / M_PER_INCH;
  const eastInches = eastM / M_PER_INCH;
  return {
    x: enu.originInches.x + northInches * n.x + eastInches * e.x,
    y: enu.originInches.y + northInches * n.y + eastInches * e.y,
  };
}

export function enuFromPhoto(photo: SurveyPhoto): SurveyEnu | null {
  const g = photo.geodesy;
  const gcp = gcpWorld(photo);
  if (!g || !gcp) return null;
  return { lat: g.lat, lng: g.lng, northDeg: g.northDeg, originInches: { ...gcp } };
}

export function checkMeasure(
  photo: SurveyPhoto,
  check: PhotoCheck = photo.check as PhotoCheck,
): { measuredInches: number; knownInches: number; residualInches: number; residualPct: number } | null {
  if (!check || check.knownInches <= 0) return null;
  const a = pixelToWorld(photo, check.ax, check.ay);
  const b = pixelToWorld(photo, check.bx, check.by);
  const measuredInches = hypot(b.x - a.x, b.y - a.y);
  const residualInches = measuredInches - check.knownInches;
  return {
    measuredInches,
    knownInches: check.knownInches,
    residualInches,
    residualPct: (residualInches / check.knownInches) * 100,
  };
}

export function checkFails(photo: SurveyPhoto): boolean {
  const m = photo.check ? checkMeasure(photo) : null;
  return !!m && Math.abs(m.residualPct) > CHECK_WARN_PCT;
}

export function associationBounds(survey: AssociationSurvey): { x: number; y: number; w: number; h: number } | null {
  if (!survey.photos.length) return null;
  let minx = Infinity;
  let miny = Infinity;
  let maxx = -Infinity;
  let maxy = -Infinity;
  for (const p of survey.photos) {
    const { w, h } = photoWorldSize(p);
    minx = Math.min(minx, p.worldOriginInches.x);
    miny = Math.min(miny, p.worldOriginInches.y);
    maxx = Math.max(maxx, p.worldOriginInches.x + w);
    maxy = Math.max(maxy, p.worldOriginInches.y + h);
  }
  const pad = yardsToInches(10);
  return { x: minx - pad, y: miny - pad, w: maxx - minx + pad * 2, h: maxy - miny + pad * 2 };
}
