<script lang="ts">
  import type { Field, League } from "../model";
  import {
    fieldCorners,
    fieldRotateHandle,
    headingUnit,
    hypot,
    inchesPerPixel,
    normFromWorld,
    overlayOutsidePhoto,
    overlaysOverlap,
    photoCalibrated,
    photoMap,
    photoWorldSize,
    checkIsAcross,
    pointInOverlay,
    pointsToSvg,
    worldToPixel,
  } from "../survey/geometry";
  import { associationBounds, checkFails, checkMeasure, formatLatLng, northHeading, worldToLatLng } from "../survey/geo";
  import {
    addOverlay,
    addPhoto,
    cloneOverlay,
    cloneSurvey,
    copyPayload,
    deleteOverlay,
    emptySurvey,
    fitNtssa,
    markCampusGcp,
    overlayFromDrag,
    pasteOverlay,
    rotateOverlay,
    scalePhotoWidth,
    setPhotoCheck,
    setPhotoScale,
    snapOverlay,
    snapPoint,
    stampClass,
    updateOverlay,
    type NtssaClass,
  } from "../survey/ops";
  import { applyOverlaysToFields } from "../survey/persist";
  import { fetchPhotoFile, paintVanSchematic, readPhotoFile } from "../survey/photo";
  import { snapPointGeometry } from "../survey/snap";
  import type { AssociationSurvey, Pt, SurveyOverlay, SurveyTool } from "../survey/types";
  import { FULL_RANGE_YD, NTSSA_DRAW, formatTape, formatYards, fullOutOfRange, parseLength, splitFeetInches, yardsToInches } from "../survey/units";
  import { fitVanAerial, placeVanLayout } from "../survey/van-layout";

  let {
    league,
    survey: surveyIn,
    onChange,
  }: {
    league: League;
    survey: AssociationSurvey;
    onChange: (survey: AssociationSurvey, fields: Field[]) => void;
  } = $props();

  let survey = $state(surveyIn?.photos ? cloneSurvey(surveyIn) : emptySurvey());
  let tool = $state<SurveyTool>("select");
  let photoId = $state(survey.photos[0]?.id || "");
  let selectedId = $state("");
  let knownLength = $state("80 yd");
  let checkLength = $state("70 yd");
  let gcpCampus = $state("Van High School");
  let drawClass = $state<"" | NtssaClass>("");
  let message = $state("Upload a satellite photo, then set the scale in yards or feet and inches.");
  let stage: SVGSVGElement | undefined = $state();
  let viewport: HTMLDivElement | undefined = $state();
  let fileInput: HTMLInputElement | undefined = $state();
  let view = $state({ x: 0, y: 0, w: 100, h: 100 });
  let spacePan = $state(false);
  let clipboard = $state<SurveyOverlay | null>(null);
  let past = $state<AssociationSurvey[]>([]);
  let future = $state<AssociationSurvey[]>([]);

  type Drag =
    | { kind: "pan"; last: Pt }
    | { kind: "draw"; a: Pt }
    | { kind: "move"; last: Pt; id: string }
    | { kind: "rotate"; id: string }
    | { kind: "scale"; n: 1 | 2; a?: Pt }
    | { kind: "ruler"; a: Pt; b?: Pt };
  let drag = $state<Drag | null>(null);
  let draft = $state<{ a: Pt; b: Pt } | null>(null);
  let scalePts = $state<{ a?: Pt; b?: Pt }>({});
  let rulerPts = $state<{ a?: Pt; b?: Pt }>({});

  const photo = $derived(survey.photos.find((p) => p.id === photoId) || survey.photos[0]);
  const calibrated = $derived(!!photo && photoCalibrated(photo));
  const overlays = $derived(survey.overlays);
  const selected = $derived(survey.overlays.find((o) => o.id === selectedId));
  const size = $derived(photo ? photoWorldSize(photo) : { w: 100, h: 100, ipp: 1 });
  const overlapping = $derived(new Set(overlapIds(overlays)));
  const handleR = $derived(Math.max(36, view.w * 0.01));
  const control = $derived(overlays.some((o) => o.source === "van-aerial") ? "van-aerial" : overlays.some((o) => o.source === "van-layout") ? "van-layout" : "");
  const northDeg = $derived(photo ? northHeading(photo) : null);
  const northRose = $derived.by(() => {
    if (!photo?.geodesy || northDeg == null) return null;
    const o = photo.worldOriginInches;
    const n = headingUnit(northDeg);
    const len = yardsToInches(18);
    const stem = { x: o.x + yardsToInches(14), y: o.y + yardsToInches(28) };
    return { stem, tip: { x: stem.x + n.x * len, y: stem.y + n.y * len }, deg: northDeg };
  });
  const vanCampus = $derived(league.campuses.find((c) => /van complex/i.test(c.name)));
  const check = $derived(photo?.check ? checkMeasure(photo) : null);
  const checkBad = $derived(!!photo && checkFails(photo));
  const aniso = $derived(!!photo && checkIsAcross(photo));

  $effect(() => {
    if (photo && (view.w === 100 || Number.isNaN(view.w))) fitPhoto();
  });

  function overlapIds(list: SurveyOverlay[]): string[] {
    const hit: string[] = [];
    for (let i = 0; i < list.length; i++) {
      for (let j = i + 1; j < list.length; j++) {
        if (overlaysOverlap(list[i], list[j])) {
          hit.push(list[i].id, list[j].id);
        }
      }
    }
    return hit;
  }

  function defaults(): Partial<SurveyOverlay> {
    const campus =
      league.campuses.find((c) => /van complex/i.test(c.name))?.name || league.campuses[0]?.name || "Van Complex";
    return {
      campus,
      parking: "Lot North",
      availableRaw: "Saturday 8:00-18:00",
      ntssaClass: drawClass || "small",
    };
  }

  function emit(next: AssociationSurvey, record = true) {
    if (record) {
      past = [...past.slice(-48), cloneSurvey(survey)];
      future = [];
    }
    survey = next;
    onChange(next, applyOverlaysToFields(league, next));
  }

  function undo() {
    if (!past.length) return;
    const prev = past[past.length - 1];
    past = past.slice(0, -1);
    future = [...future, cloneSurvey(survey)];
    survey = prev;
    onChange(survey, applyOverlaysToFields(league, survey));
  }

  function redo() {
    if (!future.length) return;
    const n = future[future.length - 1];
    future = future.slice(0, -1);
    past = [...past, cloneSurvey(survey)];
    survey = n;
    onChange(survey, applyOverlaysToFields(league, survey));
  }

  function fitPhoto() {
    if (survey.photos.length > 1) {
      const b = associationBounds(survey);
      if (b) {
        view = b;
        return;
      }
    }
    if (!photo) return;
    const origin = photo.worldOriginInches;
    view = { x: origin.x, y: origin.y, w: size.w, h: size.h };
  }

  function clientToWorld(e: { clientX: number; clientY: number }): Pt | null {
    if (!stage) return null;
    const ctm = stage.getScreenCTM();
    if (!ctm) return null;
    const pt = stage.createSVGPoint();
    pt.x = e.clientX;
    pt.y = e.clientY;
    const loc = pt.matrixTransform(ctm.inverse());
    return { x: loc.x, y: loc.y };
  }

  /** Tape and scale grab chalk (corners/edges). Draw/move also fall back to the grid. */
  function worldClick(e: { clientX: number; clientY: number }, mode: "grid" | "geom"): Pt | null {
    const raw = clientToWorld(e);
    if (!raw) return null;
    if (mode === "geom") return (survey.snap && snapPointGeometry(survey, raw, selectedId)) || raw;
    return snapPoint(survey, raw, selectedId);
  }

  function yd(n: number): string {
    return formatYards(n, 2);
  }

  async function onFiles(list: FileList | null) {
    if (!list?.length) return;
    let next = survey;
    for (const file of list) {
      try {
        const p = await readPhotoFile(file);
        next = addPhoto(next, p);
        photoId = p.id;
        message = "Click two points of a known length, or type the width of this photo in yards.";
      } catch (err) {
        message = err instanceof Error ? err.message : "Could not read that photograph.";
      }
    }
    emit(next);
    tool = "scale";
    queueMicrotask(fitPhoto);
  }

  function applyKnownInches(inches: number, fromWidth: boolean) {
    if (!photo) return;
    if (fromWidth || !scalePts.a || !scalePts.b) {
      emit(scalePhotoWidth(survey, photo.id, inches));
      message = `Photo width is ${formatTape(inches)}.`;
    } else {
      const px = (scalePts.a.x - photo.worldOriginInches.x) / size.ipp;
      const py = (scalePts.a.y - photo.worldOriginInches.y) / size.ipp;
      const qx = (scalePts.b.x - photo.worldOriginInches.x) / size.ipp;
      const qy = (scalePts.b.y - photo.worldOriginInches.y) / size.ipp;
      emit(setPhotoScale(survey, photo.id, { ax: px, ay: py, bx: qx, by: qy, knownInches: inches }));
      message = `Scale set: ${formatTape(inches)} between the two marks.`;
    }
    tool = "draw";
    scalePts = {};
    queueMicrotask(fitPhoto);
  }

  function commitScale() {
    const inches = parseLength(knownLength);
    if (!inches || inches <= 0) {
      message = "Type a length with a unit — 80 yd or 240 ft 0 in.";
      return;
    }
    applyKnownInches(inches, false);
  }

  function commitPhotoWidth() {
    const inches = parseLength(knownLength);
    if (!inches || inches <= 0) {
      message = "Type a length with a unit — 80 yd or 240 ft 0 in.";
      return;
    }
    applyKnownInches(inches, true);
  }

  function commitCheck() {
    if (!photo || !rulerPts.a || !rulerPts.b) {
      message = "Drag the ruler across a known length first, then Set check.";
      return;
    }
    const inches = parseLength(checkLength);
    if (!inches || inches <= 0) {
      message = "Type the check length — 70 yd for a 16U goal line.";
      return;
    }
    const a = worldToPixel(photo, rulerPts.a);
    const b = worldToPixel(photo, rulerPts.b);
    emit(setPhotoCheck(survey, photo.id, { ax: a.x, ay: a.y, bx: b.x, by: b.y, knownInches: inches }));
    message = `Check ${formatTape(inches)} against the scale.`;
  }

  function placeVan() {
    let next = survey;
    if (!next.photos.length) {
      const schematic = paintVanSchematic();
      next = addPhoto(next, schematic);
      photoId = schematic.id;
    }
    const id = photoId || next.photos[0]?.id;
    const p = next.photos.find((x) => x.id === id);
    if (!p || !photoCalibrated(p)) {
      message = "Set the scale in feet and inches before placing official NTSSA pitches.";
      emit(next);
      return;
    }
    emit(placeVanLayout(next, p.id));
    photoId = p.id;
    message = "Van Complex schematic: 12U, 10U, 6U/8U pack, 16U — official NTSSA yards. Drag to match the aerial.";
    queueMicrotask(fitPhoto);
  }

  async function loadVanAerial() {
    try {
      const p = await fetchPhotoFile("./van-aerial.jpg", "Van Soccer Association.jpg");
      let next = addPhoto(survey, p);
      photoId = p.id;
      next = fitVanAerial(next, p.id, vanCampus);
      emit(next);
      tool = "select";
      message = "Van aerial baseline: 12U west touchline is 80 yd north→south. Stamps sit in that frame; the pin is Van Complex lat/lng.";
      queueMicrotask(fitPhoto);
    } catch (err) {
      message = err instanceof Error ? err.message : "Could not load the Van aerial.";
    }
  }

  function fitAerial() {
    if (!photo) {
      void loadVanAerial();
      return;
    }
    const used = fitVanAerial(survey, photo.id, vanCampus);
    emit(used);
    const src = used.photos.find((p) => p.id === photo.id)?.baselineSource;
    message =
      src === "user"
        ? "Baseline is your two marks as the 12U west touchline (80 yd, north→south). Official NTSSA stamps follow that line."
        : "Registered Van crop baseline (12U west touchline = 80 yd). Click that paint and Set scale if this photo is a different crop.";
    tool = "select";
    queueMicrotask(fitPhoto);
  }

  function hitField(p: Pt): SurveyOverlay | undefined {
    for (let i = overlays.length - 1; i >= 0; i--) {
      if (pointInOverlay(overlays[i], p)) return overlays[i];
    }
    return undefined;
  }

  function onDown(e: PointerEvent) {
    if (!photo || e.button === 2) return;
    (e.currentTarget as SVGSVGElement).setPointerCapture(e.pointerId);
    const pan = tool === "pan" || spacePan || e.button === 1;
    if (pan) {
      drag = { kind: "pan", last: { x: e.clientX, y: e.clientY } };
      return;
    }
    const raw = clientToWorld(e);
    if (!raw) return;
    const p = tool === "scale" || tool === "ruler" || tool === "draw" ? worldClick(e, tool === "draw" ? "grid" : "geom") || raw : raw;
    if (tool === "scale") {
      if (!scalePts.a) {
        scalePts = { a: p };
        drag = { kind: "scale", n: 1, a: p };
        message = "Click the other end of the known length.";
      } else {
        scalePts = { ...scalePts, b: p };
        drag = { kind: "scale", n: 2, a: scalePts.a };
        message = "Type that length in yards or feet and inches, then Set scale.";
      }
      return;
    }
    if (tool === "ruler") {
      drag = { kind: "ruler", a: p, b: p };
      rulerPts = { a: p, b: p };
      return;
    }
    if (tool === "draw") {
      drag = { kind: "draw", a: p };
      draft = { a: p, b: p };
      return;
    }
    if (tool === "gcp") {
      const campus = league.campuses.find((c) => c.name === gcpCampus);
      if (campus?.lat != null && campus.lng != null && photo) {
        emit(markCampusGcp(survey, photo.id, p, { lat: campus.lat, lng: campus.lng }));
        message = `${campus.name} marked. This photograph sits on the association map.`;
        tool = "select";
        queueMicrotask(fitPhoto);
      }
      return;
    }
    if (selected && hitHandle(raw, selected)) {
      drag = { kind: "rotate", id: selected.id };
      return;
    }
    const hit = hitField(raw);
    selectedId = hit?.id || "";
    if (hit) {
      photoId = hit.photoId;
      drag = { kind: "move", last: raw, id: hit.id };
      return;
    }
    const under = survey.photos
      .slice()
      .reverse()
      .find((ph) => {
        const s = photoWorldSize(ph);
        const o = ph.worldOriginInches;
        return raw.x >= o.x && raw.x <= o.x + s.w && raw.y >= o.y && raw.y <= o.y + s.h;
      });
    if (under) photoId = under.id;
  }

  function hitHandle(p: Pt, o: SurveyOverlay): boolean {
    const h = fieldRotateHandle(o);
    return hypot(p.x - h.x, p.y - h.y) <= handleR * 1.8;
  }

  function onMove(e: PointerEvent) {
    if (!drag) return;
    if (drag.kind === "pan") {
      if (!stage) return;
      const ctm = stage.getScreenCTM();
      if (!ctm) return;
      const k = view.w / (stage.getBoundingClientRect().width || 1);
      view = {
        ...view,
        x: view.x - (e.clientX - drag.last.x) * k,
        y: view.y - (e.clientY - drag.last.y) * k,
      };
      drag = { kind: "pan", last: { x: e.clientX, y: e.clientY } };
      return;
    }
    const p =
      drag.kind === "ruler" || drag.kind === "scale"
        ? worldClick(e, "geom") || clientToWorld(e)
        : clientToWorld(e);
    if (!p) return;
    if (drag.kind === "draw") {
      draft = { a: drag.a, b: p };
    } else if (drag.kind === "move") {
      const o = survey.overlays.find((x) => x.id === drag.id);
      if (!o) return;
      const dx = p.x - drag.last.x;
      const dy = p.y - drag.last.y;
      survey = updateOverlay(survey, drag.id, { cxInches: o.cxInches + dx, cyInches: o.cyInches + dy });
      drag = { kind: "move", last: p, id: drag.id };
    } else if (drag.kind === "rotate") {
      const o = survey.overlays.find((x) => x.id === drag.id);
      if (!o) return;
      const heading = (Math.atan2(p.y - o.cyInches, p.x - o.cxInches) * 180) / Math.PI;
      survey = rotateOverlay(survey, drag.id, heading);
    } else if (drag.kind === "ruler") {
      drag = { ...drag, b: p };
      rulerPts = { a: drag.a, b: p };
    } else if (drag.kind === "scale" && drag.n === 2) {
      scalePts = { a: drag.a, b: p };
    }
  }

  function onUp(e: PointerEvent) {
    if (!drag || !photo) {
      drag = null;
      draft = null;
      return;
    }
    const p = worldClick(e, drag.kind === "ruler" || drag.kind === "scale" ? "geom" : "grid");
    if (drag.kind === "draw" && p) {
      const dist = hypot(p.x - drag.a.x, p.y - drag.a.y);
      let next = survey;
      let made: SurveyOverlay;
      if (drawClass && dist < yardsToInches(2)) {
        made = stampClass(next, photo.id, drag.a, drawClass, defaults());
      } else if (dist >= 12) {
        made = overlayFromDrag(next, photo.id, drag.a, p, defaults());
        if (drawClass) {
          made.ntssaClass = drawClass;
          const sz = NTSSA_DRAW[drawClass];
          made.lengthInches = yardsToInches(sz.lengthYd);
          made.widthInches = yardsToInches(sz.widthYd);
        }
      } else {
        drag = null;
        draft = null;
        return;
      }
      next = addOverlay(next, made);
      selectedId = made.id;
      emit(next);
      message = calibrated
        ? `${made.fieldName || "Field"} ${yd(made.lengthInches)} × ${yd(made.widthInches)} yd. Name it to write a Field record.`
        : "Drawn in pixels until you set the scale. Type a known length.";
    } else if (drag.kind === "move") {
      const o = survey.overlays.find((x) => x.id === drag.id);
      if (o) emit(updateOverlay(survey, o.id, snapOverlay(survey, o)));
    } else if (drag.kind === "rotate") {
      const o = survey.overlays.find((x) => x.id === drag.id);
      if (o) emit(updateOverlay(survey, o.id, snapOverlay(survey, o)));
    } else if (drag.kind === "ruler" && rulerPts.a && rulerPts.b) {
      const inches = hypot(rulerPts.b.x - rulerPts.a.x, rulerPts.b.y - rulerPts.a.y);
      message = `Tape: ${formatTape(inches)}  heading ${headingLabel(rulerPts.a, rulerPts.b)}`;
    }
    drag = null;
    draft = null;
  }

  function headingLabel(a: Pt, b: Pt): string {
    const d = (Math.atan2(b.y - a.y, b.x - a.x) * 180) / Math.PI;
    return `${((d + 360) % 360).toFixed(1)}°`;
  }

  function onWheel(e: WheelEvent) {
    e.preventDefault();
    const p = clientToWorld(e);
    if (!p) return;
    const factor = e.deltaY > 0 ? 1.12 : 0.89;
    const nw = view.w * factor;
    const nh = view.h * factor;
    view = {
      x: p.x - ((p.x - view.x) / view.w) * nw,
      y: p.y - ((p.y - view.y) / view.h) * nh,
      w: nw,
      h: nh,
    };
  }

  $effect(() => {
    const el = viewport;
    if (!el) return;
    const fn = (e: WheelEvent) => onWheel(e);
    el.addEventListener("wheel", fn, { passive: false });
    return () => el.removeEventListener("wheel", fn);
  });

  function patchSelected(patch: Partial<SurveyOverlay>, record = true) {
    if (!selected) return;
    emit(updateOverlay(survey, selected.id, patch), record);
  }

  function removeSelected() {
    if (!selected) return;
    const id = selected.id;
    selectedId = "";
    emit(deleteOverlay(survey, id));
  }

  function setYd(dim: "lengthInches" | "widthInches", raw: string) {
    const n = Number(raw);
    if (!Number.isFinite(n) || n <= 0) return;
    patchSelected({ [dim]: yardsToInches(n) });
  }

  function setFtIn(dim: "lengthInches" | "widthInches", feetRaw: string, inchesRaw: string) {
    const ft = Number(feetRaw);
    const inn = Number(inchesRaw);
    if (!Number.isFinite(ft) || !Number.isFinite(inn)) return;
    patchSelected({ [dim]: Math.round(ft * 12 + inn) });
  }

  function cloneSel() {
    if (!selected) return;
    const before = survey.overlays.map((o) => o.id);
    const next = cloneOverlay(survey, selected.id);
    const added = next.overlays.find((o) => !before.includes(o.id));
    if (added) selectedId = added.id;
    emit(next);
  }

  function copySel() {
    if (!selected) return;
    clipboard = copyPayload(selected);
    message = "Copied. Paste drops a twin on this photo.";
  }

  function pasteSel() {
    if (!clipboard || !photo) return;
    const next = pasteOverlay(survey, clipboard, photo.id);
    selectedId = next.overlays[next.overlays.length - 1]?.id || selectedId;
    emit(next);
  }

  function onKey(e: KeyboardEvent) {
    const t = e.target as HTMLElement;
    if (t.tagName === "INPUT" || t.tagName === "SELECT" || t.tagName === "TEXTAREA") {
      return;
    }
    if (e.code === "Space") {
      spacePan = e.type === "keydown";
      if (e.type === "keydown") e.preventDefault();
      return;
    }
    if (e.type !== "keydown") return;
    const key = e.key.toLowerCase();
    if ((e.ctrlKey || e.metaKey) && key === "z") {
      e.preventDefault();
      if (e.shiftKey) redo();
      else undo();
      return;
    }
    if ((e.ctrlKey || e.metaKey) && key === "y") {
      e.preventDefault();
      redo();
      return;
    }
    if ((e.ctrlKey || e.metaKey) && key === "c") {
      e.preventDefault();
      copySel();
      return;
    }
    if ((e.ctrlKey || e.metaKey) && key === "v") {
      e.preventDefault();
      pasteSel();
      return;
    }
    if ((e.ctrlKey || e.metaKey) && key === "d") {
      e.preventDefault();
      cloneSel();
      return;
    }
    if (key === "v") tool = "select";
    if (key === "d") tool = "draw";
    if (key === "c") tool = "scale";
    if (key === "r") tool = "ruler";
    if (key === "g") tool = "gcp";
    if (key === "h") tool = "pan";
    if (key === "delete" || key === "backspace") {
      if (selected) {
        const id = selected.id;
        selectedId = "";
        emit(deleteOverlay(survey, id));
      }
    }
    if (key === "escape") {
      selectedId = "";
      drag = null;
      draft = null;
      tool = "select";
    }
    if (selected && (e.key === "ArrowLeft" || e.key === "ArrowRight" || e.key === "ArrowUp" || e.key === "ArrowDown")) {
      e.preventDefault();
      const step = survey.gridPitchInches || yardsToInches(1);
      const dx = e.key === "ArrowLeft" ? -step : e.key === "ArrowRight" ? step : 0;
      const dy = e.key === "ArrowUp" ? -step : e.key === "ArrowDown" ? step : 0;
      emit(
        updateOverlay(survey, selected.id, {
          cxInches: selected.cxInches + dx,
          cyInches: selected.cyInches + dy,
        }),
      );
    }
    if (selected && (e.key === "[" || e.key === "]")) {
      const delta = e.key === "]" ? 1 : -1;
      emit(rotateOverlay(survey, selected.id, selected.headingDeg + (e.shiftKey ? delta * 5 : delta)));
    }
  }

  function gridLines(): { x1: number; y1: number; x2: number; y2: number }[] {
    if (!photo) return [];
    const origin = photo.worldOriginInches;
    const pitch = survey.gridPitchInches || yardsToInches(1);
    const lines: { x1: number; y1: number; x2: number; y2: number }[] = [];
    const maxLines = 80;
    const step = size.w / pitch > maxLines ? Math.ceil(size.w / pitch / maxLines) * pitch : pitch;
    for (let x = origin.x; x <= origin.x + size.w + 1; x += step) {
      lines.push({ x1: x, y1: origin.y, x2: x, y2: origin.y + size.h });
    }
    for (let y = origin.y; y <= origin.y + size.h + 1; y += step) {
      lines.push({ x1: origin.x, y1: y, x2: origin.x + size.w, y2: y });
    }
    return lines;
  }

  const rulerInches = $derived(
    rulerPts.a && rulerPts.b ? hypot(rulerPts.b.x - rulerPts.a.x, rulerPts.b.y - rulerPts.a.y) : 0,
  );
  const barInches = yardsToInches(50);
</script>

