    <button type="button" class="chip" data-tool="draw" aria-current={tool === "draw"} onclick={() => (tool = "draw")}>Draw</button>
    <button type="button" class="chip" data-tool="scale" aria-current={tool === "scale"} onclick={() => (tool = "scale")}>Scale</button>
    <button type="button" class="chip" data-tool="ruler" aria-current={tool === "ruler"} onclick={() => (tool = "ruler")}>Ruler</button>
    <button type="button" class="chip" data-tool="gcp" aria-current={tool === "gcp"} onclick={() => (tool = "gcp")}>Campus pin</button>
    <button type="button" class="chip" data-tool="pan" aria-current={tool === "pan"} onclick={() => (tool = "pan")}>Pan</button>
