        <option value="">free</option>
        <option value="small">4v4 35×25</option>
        <option value="medium">7v7 65×45</option>
        <option value="nine">9v9 80×55</option>
        <option value="full">11v11 110×70</option>
      </select>
    </label>
    <button type="button" class="quiet" data-action="clone-field" disabled={!selected} onclick={cloneSel}>Clone</button>
    <button type="button" class="quiet" data-action="copy-field" disabled={!selected} onclick={copySel}>Copy</button>
    <button type="button" class="quiet" data-action="paste-field" disabled={!clipboard} onclick={pasteSel}>Paste</button>
    <button type="button" class="quiet" data-action="undo-survey" disabled={!past.length} onclick={undo}>Undo</button>
  </header>

  <div class="survey-body">
    <aside class="survey-rail" data-survey-rail>
      <h3>Photos</h3>
      {#each survey.photos as p}
        <button
          type="button"
          class="chip"
          data-photo-tab={p.id}
          aria-current={photo?.id === p.id}
