        </label>
      {:else}
        <svg
          bind:this={stage}
          class="survey-stage"
          data-survey-stage
          role="img"
          aria-label="Association aerial with field overlays"
          viewBox="{view.x} {view.y} {view.w} {view.h}"
          preserveAspectRatio="none"
          onpointerdown={onDown}
          onpointermove={onMove}
          onpointerup={onUp}
        >
