            {@const m = photoMap(p)}
            <image
              data-survey-photo={p.id}
              href={p.dataUrl}
              width={p.pixelWidth}
              height={p.pixelHeight}
              transform="matrix({m.a} {m.b} {m.c} {m.d} {m.e} {m.f})"
              opacity={p.id === photo?.id ? 1 : 0.55}
              preserveAspectRatio="none"
            />
          {/each}
          <g data-survey-grid="yes" opacity="0.35" pointer-events="none">
            {#each gridLines() as ln}
              <line x1={ln.x1} y1={ln.y1} x2={ln.x2} y2={ln.y2} stroke="#163528" stroke-width={view.w * 0.0006} />
            {/each}
          </g>
          {#each overlays as o}
            {@const corners = fieldCorners(o)}
            {@const handle = fieldRotateHandle(o)}
            {@const host = survey.photos.find((p) => p.id === o.photoId) || photo}
            {@const overflow = host ? overlayOutsidePhoto(o, host) : false}
            <g
              data-survey-field={o.id}
              data-field-name={o.fieldName}
              data-ntssa={o.ntssaClass}
              data-length-yd={yd(o.lengthInches)}
              data-width-yd={yd(o.widthInches)}
              data-cx-yd={yd(o.cxInches)}
              data-cy-yd={yd(o.cyInches)}
              data-u={host ? normFromWorld(host, { x: o.cxInches, y: o.cyInches }).x.toFixed(4) : ""}
              data-v={host ? normFromWorld(host, { x: o.cxInches, y: o.cyInches }).y.toFixed(4) : ""}
              data-source={o.source || "drawn"}
              data-heading={o.headingDeg.toFixed(1)}
              data-lat={host ? (worldToLatLng(host, { x: o.cxInches, y: o.cyInches })?.lat.toFixed(6) ?? "") : ""}
              data-lng={host ? (worldToLatLng(host, { x: o.cxInches, y: o.cyInches })?.lng.toFixed(6) ?? "") : ""}
              data-selected={selectedId === o.id ? "yes" : "no"}
              data-overlap={overlapping.has(o.id) ? "yes" : "no"}
              data-overflow={overflow ? "yes" : "no"}
              data-full-legal={o.ntssaClass === "full" ? (fullOutOfRange(o.lengthInches, o.widthInches) ? "no" : "yes") : ""}
            >
              <polygon
                points={pointsToSvg(corners)}
                fill={selectedId === o.id ? "rgba(232, 184, 74, 0.28)" : overlapping.has(o.id) ? "rgba(154, 59, 47, 0.28)" : "rgba(30, 58, 95, 0.22)"}
                stroke={overflow ? "#9a3b2f" : selectedId === o.id ? "#c9922a" : "#1e3a5f"}
                stroke-width={view.w * 0.002}
              />
              <text x={o.cxInches} y={o.cyInches} text-anchor="middle" dominant-baseline="middle" fill="#163528" font-size={Math.max(48, view.w * 0.018)} font-family="Georgia, serif">
                {o.fieldName || o.ntssaClass} · {yd(o.lengthInches)}×{yd(o.widthInches)} yd
              </text>
              {#if o.ntssaClass === "full" && fullOutOfRange(o.lengthInches, o.widthInches)}
                <text x={o.cxInches} y={o.cyInches + Math.max(40, view.w * 0.016)} text-anchor="middle" fill="#9a3b2f" font-size={Math.max(36, view.w * 0.014)}>outside NTSSA 11v11</text>
              {/if}
              {#if selectedId === o.id}
                <circle data-handle="rotate" cx={handle.x} cy={handle.y} r={handleR} fill="#e8b84a" stroke="#163528" stroke-width={view.w * 0.001} />
              {/if}
            </g>
          {/each}
          {#if draft}
            <rect
              data-survey-draft
              x={Math.min(draft.a.x, draft.b.x)}
              y={Math.min(draft.a.y, draft.b.y)}
              width={Math.abs(draft.b.x - draft.a.x)}
              height={Math.abs(draft.b.y - draft.a.y)}
              fill="rgba(232, 184, 74, 0.18)"
              stroke="#c9922a"
              stroke-dasharray="40 20"
              stroke-width={view.w * 0.002}
            />
          {/if}
          {#if scalePts.a}
            <circle data-scale-a cx={scalePts.a.x} cy={scalePts.a.y} r={handleR} fill="#e8b84a" />
          {/if}
          {#if scalePts.b}
            <circle data-scale-b cx={scalePts.b.x} cy={scalePts.b.y} r={handleR} fill="#e8b84a" />
            <line x1={scalePts.a?.x} y1={scalePts.a?.y} x2={scalePts.b.x} y2={scalePts.b.y} stroke="#e8b84a" stroke-width={view.w * 0.003} />
          {/if}
          {#if northRose}
            <g data-north-rose data-north-deg={northRose.deg.toFixed(1)}>
              <line x1={northRose.stem.x} y1={northRose.stem.y} x2={northRose.tip.x} y2={northRose.tip.y} stroke="#9a3b2f" stroke-width={view.w * 0.003} />
              <text x={northRose.tip.x} y={northRose.tip.y} text-anchor="middle" dominant-baseline="middle" fill="#9a3b2f" font-size={Math.max(48, view.w * 0.022)} font-weight="700">N</text>
            </g>
          {/if}
          {#if rulerPts.a && rulerPts.b}
            <g data-survey-ruler data-ruler-length={formatTape(rulerInches)}>
              <line x1={rulerPts.a.x} y1={rulerPts.a.y} x2={rulerPts.b.x} y2={rulerPts.b.y} stroke="#9a3b2f" stroke-width={view.w * 0.003} />
              <text x={(rulerPts.a.x + rulerPts.b.x) / 2} y={(rulerPts.a.y + rulerPts.b.y) / 2 - view.w * 0.012} text-anchor="middle" fill="#9a3b2f" font-size={Math.max(40, view.w * 0.02)}>
                {formatTape(rulerInches)}
              </text>
            </g>
          {/if}
        </svg>
        <div class="survey-scalebar" data-scale-bar>
          <i style="width: {Math.max(24, (barInches / view.w) * 100)}%"></i>
          <span>50 yd</span>
        </div>
      {/if}
    </div>

    <aside class="survey-inspector" data-survey-inspector>
      <h3>Scale</h3>
      <label>Known length
        <input data-field="known-length" bind:value={knownLength} placeholder="80 yd or 240 ft" />
      </label>
      <p class="row">
        <button type="button" class="quiet" data-action="commit-scale" onclick={commitScale}>Set scale</button>
        <button type="button" class="quiet" data-action="scale-photo-width" onclick={commitPhotoWidth}>Photo is this wide</button>
      </p>
      <p class="meta" data-scale-status>
        {#if photo && calibrated}
          1 px = {((inchesPerPixel(photo) || 0) / 12).toFixed(3)} ft
          {#if photo.baselineSource}
            · baseline {photo.baselineSource === "user" ? "your 12U touchline" : "registered Van crop"}
          {/if}
        {:else}
          Not calibrated — do not trust pixel boxes.
        {/if}
      </p>
      <p class="meta">Van Complex: click the 12U west touchline north to south, type 80 yd, then Fit Van aerial — a different crop still lands.</p>
      <h3>Check</h3>
      <label>Known check
        <input data-field="check-length" bind:value={checkLength} placeholder="70 yd" />
      </label>
      <button type="button" class="quiet" data-action="commit-check" onclick={commitCheck}>Tape is this check</button>
      {#if check}
        <p class="meta" data-check-status>
          Scale reads {formatTape(check.measuredInches)} for a {formatTape(check.knownInches)} check
          ({check.residualPct >= 0 ? "+" : ""}{check.residualPct.toFixed(1)}%).
        </p>
        {#if aniso && !checkBad}
          <p class="meta" data-check-repaired>Across scale repaired from this check. Along stays the 12U (or photo) baseline.</p>
        {/if}
        {#if checkBad}
          <p class="flag" data-check-warn>Second control disagrees with the scale and is not across it, so it cannot repair. A bleacher shot needs a perpendicular check (16U goal line).</p>
        {/if}
      {:else}
        <p class="meta">Drag a ruler along a second known length (16U goal line is 70 yd) and set the check.</p>
      {/if}
      <h3>Campus pin</h3>
      <label>This click is
        <select data-field="gcp-campus" bind:value={gcpCampus}>
          {#each league.campuses.filter((c) => c.lat != null && c.lng != null) as c}
            <option value={c.name}>{c.name}</option>
          {/each}
        </select>
      </label>
      <p class="meta">Campus pin places this photograph on the association map from lat/lng.</p>

      {#if selected}
        <h3>Pitch</h3>
        <label>Name
          <input data-field="field-name" value={selected.fieldName} oninput={(e) => patchSelected({ fieldName: e.currentTarget.value }, false)} />
        </label>
        <label>NTSSA class
          <select data-field="ntssa-class" value={selected.ntssaClass} onchange={(e) => patchSelected({ ntssaClass: e.currentTarget.value as NtssaClass })}>
            <option value="small">small 4v4 35×25 yd · 6U/8U</option>
            <option value="medium">medium 7v7 65×45 yd · 10U</option>
            <option value="nine">nine 9v9 80×55 yd · 12U</option>
            <option value="full">full 11v11 110×70 yd · 14U/16U</option>
          </select>
        </label>
        <p class="meta">Official {NTSSA_DRAW[selected.ntssaClass].lengthYd}×{NTSSA_DRAW[selected.ntssaClass].widthYd} yd ({NTSSA_DRAW[selected.ntssaClass].ages}). 11v11 legal window {FULL_RANGE_YD.lengthMin}–{FULL_RANGE_YD.lengthMax} × {FULL_RANGE_YD.widthMin}–{FULL_RANGE_YD.widthMax} yd.</p>
        <button type="button" class="quiet" data-action="fit-ntssa" onclick={() => selected && emit(fitNtssa(survey, selected.id))}>Fit official size</button>
        {#if selected.ntssaClass === "full"}
          <p class="row">
            <button type="button" class="quiet" data-action="full-short" onclick={() => patchSelected({ lengthInches: yardsToInches(100), widthInches: yardsToInches(70) })}>100×70</button>
            <button type="button" class="quiet" data-action="full-mid" onclick={() => patchSelected({ lengthInches: yardsToInches(110), widthInches: yardsToInches(70) })}>110×70</button>
            <button type="button" class="quiet" data-action="full-long" onclick={() => patchSelected({ lengthInches: yardsToInches(120), widthInches: yardsToInches(80) })}>120×80</button>
          </p>
          {#if fullOutOfRange(selected.lengthInches, selected.widthInches)}
            <p class="flag" data-illegal-full>11v11 must be {FULL_RANGE_YD.lengthMin}–{FULL_RANGE_YD.lengthMax} × {FULL_RANGE_YD.widthMin}–{FULL_RANGE_YD.widthMax} yd. This tape is outside NTSSA.</p>
          {/if}
        {/if}
        <label>Length (yd)
          <input data-field="length-yd" type="number" step="0.01" value={yd(selected.lengthInches)} onchange={(e) => setYd("lengthInches", e.currentTarget.value)} />
        </label>
        <label>Width (yd)
          <input data-field="width-yd" type="number" step="0.01" value={yd(selected.widthInches)} onchange={(e) => setYd("widthInches", e.currentTarget.value)} />
        </label>
        <div class="survey-ftin">
          <label>Length ft
            <input data-field="length-ft" type="number" value={splitFeetInches(selected.lengthInches).feet} onchange={(e) => setFtIn("lengthInches", e.currentTarget.value, String(splitFeetInches(selected.lengthInches).inches))} />
          </label>
          <label>in
            <input data-field="length-in" type="number" value={splitFeetInches(selected.lengthInches).inches} onchange={(e) => setFtIn("lengthInches", String(splitFeetInches(selected.lengthInches).feet), e.currentTarget.value)} />
          </label>
        </div>
        <div class="survey-ftin">
          <label>Width ft
            <input data-field="width-ft" type="number" value={splitFeetInches(selected.widthInches).feet} onchange={(e) => setFtIn("widthInches", e.currentTarget.value, String(splitFeetInches(selected.widthInches).inches))} />
          </label>
          <label>in
            <input data-field="width-in" type="number" value={splitFeetInches(selected.widthInches).inches} onchange={(e) => setFtIn("widthInches", String(splitFeetInches(selected.widthInches).feet), e.currentTarget.value)} />
          </label>
        </div>
        <label>Heading
          <input data-field="heading" type="number" step="0.1" value={selected.headingDeg.toFixed(1)} onchange={(e) => patchSelected({ headingDeg: Number(e.currentTarget.value) })} />
        </label>
        <label>Campus
          <select data-field="campus" value={selected.campus} onchange={(e) => patchSelected({ campus: e.currentTarget.value })}>
            {#each league.campuses as c}
              <option value={c.name}>{c.name}</option>
            {/each}
          </select>
        </label>
        <label>Parking
          <input data-field="parking" value={selected.parking} oninput={(e) => patchSelected({ parking: e.currentTarget.value }, false)} />
        </label>
        <label>Hours
          <input data-field="hours" value={selected.availableRaw} oninput={(e) => patchSelected({ availableRaw: e.currentTarget.value }, false)} />
        </label>
        {#if photo}
          {@const ll = worldToLatLng(photo, { x: selected.cxInches, y: selected.cyInches })}
          {#if ll}
            <p class="meta" data-field-ll>{formatLatLng(ll.lat, ll.lng)}</p>
          {/if}
        {/if}
        <p class="meta" data-field-link>
          {#if selected.fieldName}
            Writes Field record “{selected.fieldName}” · {selected.ntssaClass} · {selected.campus}
          {:else}
            Name the pitch to link it into the league Fields list.
          {/if}
        </p>
        {#if overlapping.has(selected.id)}
          <p class="flag" data-overlap-warn>Overlaps another pitch.</p>
        {/if}
        {#if photo && overlayOutsidePhoto(selected, photo)}
